import urllib.request
import re

# Let me try another approach - find data from different sources
urls = [
    "https://www.usinflationcalculator.com/inflation/consumer-price-index-and-annual-percent-changes-1947-2008/",
    "https://www.in2013dollars.com/consumer-price-index/1969"
]

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'}

for url in urls:
    try:
        print(f"\nTrying: {url}")
        req = urllib.request.Request(url, headers=headers)
        with urllib.request.urlopen(req, timeout=15) as response:
            html = response.read().decode('utf-8')
            # Look for 1969 November data
            # Search for table with CPI data
            if '1969' in html:
                # Look for specific month data
                match = re.search(r'1969.*?Nov.*?\d+\.\d+', html)
                if match:
                    print(f"Found: {match.group(0)[:100]}")
                else:
                    # Try to find November specifically
                    match2 = re.search(r'Nov[^0-9]*1969[^<]*<td[^>]*>(\d+\.\d+)</td>', html)
                    if match2:
                        print(f"Found Nov 1969: {match2.group(1)}")
    except Exception as e:
        print(f"Error: {e}")
EOF
